-- 092: Parque de Atracciones de Madrid and Blackpool Pleasure Beach from RCDB
-- via Carter's screenshots, 2026-10-31. Fills bare rows only (no length; the
-- Steeplechase tracks, which RCDB gives no length, on no maker).
--   Grand National (Left)/(Right): the same figures on both tracks (Carter: "2
--     same stats on both"); Steeplechase Green/Red/Yellow likewise, three tracks.
--   Big One: year not on the screenshot, so only the stats.
--   Big Dipper: SBNO since 24 Jul 2026, not marked closed (standing, may return).
--   Padrinos Voladores is RCDB's "Flying Godparents" (Zamperla Air Force).
-- New, removed: Space Invader 2 (Zierer Four Man Bob, 1984-2008) and Circus Clown
-- (Pinfari, by 1989-2008).
-- Relocation linked: Space Invader 2 -> Astro Storm (Brean Theme Park, home).
-- Not linked: Infusion (<- Traumatizer, Southport, not a park here); Circus
-- Clown (Harbour Park / Wicksteed Park stops not in the database; Oakwood's
-- Circus Clown is a different Wacky Worm). New model names: "Maurer SkyLoop",
-- "Zamperla Air Force", "Arrow Steeplechase". Safe to run twice.
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 10, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv', 'dur', 'yr', 'opened', 'openedPrec'), 'via', '092') FROM coasters WHERE name = 'Abismo' AND park = 'Parque de Atracciones de Madrid' AND l IS NULL;
UPDATE coasters SET manu = 'Maurer Rides', model = 'Maurer SkyLoop', h = 160.8, s = 65.2, l = 1345.1, inv = 2, dur = 60, yr = 2006, opened = '2006-06-27', openedPrec = 'day' WHERE name = 'Abismo' AND park = 'Parque de Atracciones de Madrid' AND l IS NULL;
