INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Space Invader 2', 'Pleasure Beach Resort', 'Steel', 'Zierer', 'Zierer Four Man Bob', NULL, NULL, NULL, 0, 90, 1984, '1984', 'year', '2008', 'year', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Space Invader 2' AND park = 'Pleasure Beach Resort');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Space Invader 2' AND c.park = 'Pleasure Beach Resort' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Circus Clown', 'Pleasure Beach Resort', 'Steel', 'Pinfari', NULL, NULL, NULL, NULL, 0, 100, 1989, '1989', 'year', '2008', 'year', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Circus Clown' AND park = 'Pleasure Beach Resort');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Circus Clown' AND c.park = 'Pleasure Beach Resort' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Astro Storm' AND h.park = 'Brean Theme Park' AND (c.id = h.id OR (c.name = 'Space Invader 2' AND c.park = 'Pleasure Beach Resort'));
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '092') FROM coasters h WHERE h.name = 'Astro Storm' AND h.park = 'Brean Theme Park' AND (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id) > 1 AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND a.detail LIKE '%"via":"092"%' AND json_extract(a.detail, '$.ride') = h.id);
